def fitr(cols):
    A=np.column_stack(cols)
    c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
    return np.sum((A@c-dP_dt)**2)/np.sum((dP_dt-dP_dt.mean())**2), c
